package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.hibernate.annotations.BatchSize;

/** A claim a person on a sheet has made: an amount (two decimals), a date, a note and a status. A negative amount
 *  makes it a correction of the SETTLED claim of the same person whose number it names. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    /** The day the claim is due by: fixed when it is added, from its date and its person's own terms, else the
     *  terms of their grade in force then, else the sheet's then; it does not change when the terms or its date
     *  change later. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number on its sheet, given when it is opened: sheet-wide (1, 2, ...), or within its period
     *  (P1-1, or X-1 in no period) while the sheet numbers per period; none while a draft. A void claim keeps
     *  the number it had, and that number is never given again. */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; none while not settled, or if its grade had no rate then. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** The signed-in name of the user who opened the claim; none while a draft. */
    @Column(name = "opened_by", length = 100)
    private String openedBy;

    /** Whether the claim is bound by its person's last statement. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim had at its person's last statement, while bound by it; none if it had none then. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the SETTLED claim of the same person a correction corrects; none on any other claim. */
    @Column(name = "corrects")
    private String corrects;

    /** The number of the claim this one was split off; none on any other claim. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The day an OPEN claim is deferred until; none if it was never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** How many proofs have been given for the claim. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The signed-in name of the user who has the claim's editor open, locking it for other users until they save
     *  or cancel or the sheet's today changes; none when no one has. */
    @Column(name = "locked_by", length = 100)
    private String lockedBy;

    /** Whether the claim was added while the period its date is in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** When the claim was listed under its person, in the sheet's order: given when it is added and again when it
     *  is reassigned, so a person's claims list newest first by it. */
    @Column(name = "listed", nullable = false)
    private long listed;

    /** The claim's status log, oldest first: a line for each status it has had, the DRAFT it was added as first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    @BatchSize(size = 100)
    private List<ClaimLogEntry> log = new ArrayList<>();

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
            String corrects, long listed) {
        this.dueBy = dueBy;
        this.sheetId = sheetId;
        this.listed = listed;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public long getListed() {
        return listed;
    }

    /** Move the claim to another person, listed as their newest claim. */
    public void reassign(Long personId, long listed) {
        this.personId = personId;
        this.listed = listed;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    /** Whether the claim is a correction: its amount is negative. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Whether a statement binds the claim now: it is stated and not PENDING (a PENDING claim follows its live
     *  figure). A bound claim keeps its bound figure, even when it had none (n/a). */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** The figure a statement binds the claim to now: its stated one, except while PENDING, when no statement
     *  binds it and it follows its live figure; null when not bound, or bound with no figure (n/a). */
    public BigDecimal getBoundDue() {
        return status == ClaimStatus.PENDING ? null : statedDue;
    }

    /** Bind the claim to the figure it has at a statement. */
    public void bind(BigDecimal figure) {
        this.stated = true;
        this.statedDue = figure;
    }

    /** Leave the claim unbound by a statement, so it is live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    /** Make the claim OPEN as one split off another: numbered, opened by this user and naming the claim it was
     *  split from. */
    public void openAsSplit(String number, String openedBy, String splitFrom) {
        this.status = ClaimStatus.OPEN;
        this.number = number;
        this.openedBy = openedBy;
        this.splitFrom = splitFrom;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    /** Whether the claim is deferred on this day: it is OPEN and deferred until a later day. While deferred it
     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    public int getProofs() {
        return proofs;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    /** Mark the claim as added while its period was soft-closed. */
    public void markLateEntry() {
        this.lateEntry = true;
    }

    /** Count one more proof given for the claim. */
    public void addProof() {
        proofs++;
    }

    /** The status the claim had at the end of {@code day}, as its log records it: the last line dated on or before
     *  it; null when the claim was added after it. */
    public ClaimStatus statusAt(LocalDate day) {
        ClaimStatus at = null;
        for (ClaimLogEntry line : log) {
            if (!line.getOn().isAfter(day)) {
                at = line.getStatus();
            }
        }
        return at;
    }

    /** The sheet's today on which the claim last became SETTLED, as its log records it; null when it never did. */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogEntry line : log) {
            if (line.getStatus() == ClaimStatus.SETTLED) {
                on = line.getOn();
            }
        }
        return on;
    }

    /** The claim's status log, oldest first. */
    public List<ClaimLogEntry> getLog() {
        return Collections.unmodifiableList(log);
    }

    /** Log the status the claim has now, taken by this user on this day, at the due it has at this moment. */
    public void logStatus(String user, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogEntry(status, user, on, due));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and a grade (A, B or C), dated: each grade is in force from its from-date. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded for the person; the first given has no from-date (from the beginning of time). */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's holds: their open claims dated within one, and not bound by a statement, count in no live
     *  total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** Raised on every save; an edit made from an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(null, grade));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, in the order they take effect. */
    public List<GradeFrom> getGrades() {
        return grades.stream().sorted(GradeFrom.BY_FROM).toList();
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it. A null date
     *  takes the latest grade recorded. */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> date == null || g.getFromDate() == null || !g.getFromDate().isAfter(date))
                .max(GradeFrom.BY_FROM)
                .orElseGet(() -> grades.stream().min(GradeFrom.BY_FROM).orElseThrow())
                .getGrade();
    }

    /** Record {@code grade} from {@code from}, replacing the grade recorded from that same date, if any. */
    public void setGradeFrom(LocalDate from, String grade) {
        grades.removeIf(g -> Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(from, grade));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Retired as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The holds recorded, in the order they start. */
    public List<Hold> getHolds() {
        return holds.stream().sorted(Hold.BY_FROM).toList();
    }

    public void addHold(Hold hold) {
        holds.add(hold);
    }

    /** Whether a claim of this person counts in the live totals on the sheet's {@code today}: an OPEN or PENDING one
     *  dated within a hold, or any once {@code today} reaches the retirement date, does not, unless a statement
     *  binds it. */
    public boolean counts(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts in the figures of a period ending {@code end}: by the status it had at
     *  the end of that day, left out when held or retired as the live totals on the sheet's {@code today} say. */
    public boolean countsAtEnd(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus at = claim.statusAt(end);
        return at != null && at.counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts when no statement binds it, as a new statement finds it. */
    public boolean countsUnbound(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !heldOn(claim, today);
    }

    /** Whether the claim is open and dated within one of the person's holds, or open once {@code today} reaches
     *  the person's retirement date. */
    private boolean heldOn(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen()
                && (retiredOn(today) || holds.stream().anyMatch(h -> h.covers(claim.getDate())));
    }

    /** Whether the retirement date is reached on {@code date}: set, and on or before it. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** Whether a claim dated {@code date} is refused: one dated after the retirement date. */
    public boolean refusesClaimOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;
import java.util.Comparator;

/** A hold on a person from its from-date to its to-date, both inclusive; a null to-date does not end. */
@Embeddable
public class Hold {

    /** Orders holds by the date they start. */
    public static final Comparator<Hold> BY_FROM = Comparator.comparing(Hold::getFromDate);

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected Hold() {
    }

    public Hold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether {@code date} is within the hold. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(fromDate) && (toDate == null || !date.isAfter(toDate));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
