142	        Rollup.Figures before = rollup.of(sheetId);
143	        claim.setAmount(scaled(amount));
144	        claim.setCorrects(corrects);
145	        claim.setDate(date != null ? date : today);
146	        claim.setNote(noteOf(note));
147	        claim.setLockedBy(null);
148	        Claim edited = claims.saveAndFlush(claim);
149	        Person person = people.findByIdAndSheetId(edited.getPersonId(), sheetId).orElseThrow();
150	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_EDITED", user, person, edited, edited.getNumber()));
151	        rollup.recordChanges(sheetId, user, before);
