155	    /**
156	     * Move a claim to a new status; a move its current status does not allow is refused. Opening a
157	     * claim gives it its next number (the sheet's next, or the next in its period while the sheet numbers per
158	     * period) and records who opened it; voiding it keeps its number, which is
159	     * never given again; settling it fixes its due: the figure a statement binds it to, else its amount
160	     * at the rate in force on its date of its person's grade in force on that date, as rates are now, with the late charge it has gained
161	     * added on top, so later rate changes leave it as it is. The user
162	     * who opened a claim cannot settle it, and a clerk settling it when that due is above the sheet's clerk limit
163	     * makes it PENDING instead, for a steward to approve or reject (a claim with no due is within any limit); a
164	     * steward settles anything. Opening, settling and voiding are each refused for a role the sheet's permission
165	     * matrix does not allow. Only a steward may void a SETTLED claim, and only within {@value #SETTLED_VOID_DAYS}
166	     * days of the day its log records it settled, by the sheet's today; its frozen figure then leaves every total
167	     * and the audit line ends with it as reversed. A claim dated inside a closed period cannot move. The sheet is locked
168	     * first, so moves on one sheet are made one at a time and no number is given twice.
169	     */
170	    @Transactional
171	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
172	        sheets.load(sheetId, user);
173	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
174	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
175	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
176	        refuseIfClosed(sheetId, claim.getDate());
177	        if (!claim.getStatus().canBecome(next)) {
178	            throw new ResponseStatusException(HttpStatus.CONFLICT,
179	                    "A " + claim.getStatus() + " claim cannot become " + next);
180	        }
181	        String action = switch (next) {
182	            case OPEN -> "open";
183	            case SETTLED -> "settle";
184	            case VOID -> "void";
185	            default -> null;
186	        };
187	        if (action != null && !sheet.allows(action, roles.roleOf(sheetId, user))) {
188	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
189	        }
190	        boolean voidsSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
191	        if (voidsSettled) {
192	            refuseSettledVoid(sheet, user, claim);
193	        }
194	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
195	            throw new ResponseStatusException(HttpStatus.CONFLICT,
196	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
197	        }
198	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
199	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
200	        }
201	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
202	        BigDecimal due = dueNow(sheet, claim, person);
203	        if (next == ClaimStatus.SETTLED) {
204	            refuseUnproven(sheet, claim, due);
205	        }
206	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheet, user, due)) {
207	            next = ClaimStatus.PENDING;
208	        }
209	        Rollup.Figures before = rollup.of(sheetId);
210	        String number = claim.getNumber();
211	        claim.setStatus(next);
212	        if (next == ClaimStatus.OPEN) {
213	            number = nextNumber(sheet, claim.getDate());
214	            claim.setNumber(number);
215	            claim.setOpenedBy(user);
216	        } else if (next == ClaimStatus.SETTLED) {
217	            claim.setSettledDue(due);
218	        }
219	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
220	        Claim changed = claims.saveAndFlush(claim);
221	        String event = switch (next) {
222	            case OPEN -> "CLAIM_OPENED";
223	            case PENDING -> "CLAIM_PENDING";
224	            case SETTLED -> "CLAIM_SETTLED";
225	            case VOID -> "CLAIM_VOIDED";
226	            case DRAFT -> throw new IllegalStateException();
227	        };
228	        String line = entry(event, user, person, changed, number);
229	        if (next == ClaimStatus.SETTLED) {
230	            line += " due=" + dueText(changed);
231	        } else if (voidsSettled) {
232	            line += " reversed=" + dueText(changed);
233	        }
234	        audit.recordChangeOnCommit(sheetId, user, line);
235	        if (next == ClaimStatus.SETTLED) {
236	            watches.notifyWatchers(sheetId, user, person, number);
237	        }
238	        rollup.recordChanges(sheetId, user, before);
239	        return changed;
240	    }
