270	     *  period gives it the next number of its new period's sequence (its old number is never given again). Refused
271	     *  for anyone but a steward, a claim in any other status, a claim dated inside a closed period, a new date inside
272	     *  one and a new date after its person retired. */
273	    @Transactional
274	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
275	        sheets.load(sheetId, user);
276	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
277	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
278	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
