484	    /** Split an amount (more than 0.00 and less than its amount) off an OPEN claim: it keeps the rest and loses any
485	     *  figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the same date
486	     *  and note, the next number, opened by this user, a due-by fixed now from the terms in force on the date and
487	     *  naming the original as the claim it was split from, is listed as the person's newest. Refused for a claim
488	     *  that is not OPEN or is deferred, one dated inside a closed period, an amount out of range, and a role the
489	     *  permission matrix does not allow to open a claim. */
490	    @Transactional
491	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
492	        sheets.load(sheetId, user);
493	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
494	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
495	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
496	        refuseIfClosed(sheetId, claim.getDate());
497	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
498	            throw new ResponseStatusException(HttpStatus.CONFLICT,
499	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one not deferred can");
500	        }
501	        if (!sheet.allows("open", roles.roleOf(sheetId, user))) {
502	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
503	        }
504	        BigDecimal part = scaled(amount);
505	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
506	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
507	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
508	        }
509	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
510	        Rollup.Figures before = rollup.of(sheetId);
511	        claim.setAmount(claim.getAmount().subtract(part));
512	        claim.unbind();
513	        Claim original = claims.saveAndFlush(claim);
514	        LocalDate date = original.getDate();
515	        LocalDate dueBy = date.plusDays(termsOf(sheet, person, date));
516	        Claim added = new Claim(sheetId, person.getId(), part, date, dueBy, original.getNote(), null,
517	                claims.lastListed(sheetId) + 1);
518	        added.openAsSplit(nextNumber(sheet, date), user, original.getNumber());
519	        added.logStatus(user, sheet.getToday(), shownDue(sheet, added, person));
520	        added = claims.saveAndFlush(added);
521	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_SPLIT", user, person, original, original.getNumber())
522	                + " into=" + added.getNumber());
523	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_OPENED", user, person, added, added.getNumber()));
524	        rollup.recordChanges(sheetId, user, before);
525	        return new Split(original, added);
526	    }
