544	    /** The due a claim would be settled at now: its bound figure, else its live one, with the late charge it has
545	     *  gained on top, raised to the floor in force on its date; null when it has no figure. */
546	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
547	        BigDecimal live = liveNow(sheet, claim, person);
548	        // Settling freezes the claim's figure (its bound one, else its live one) with the late charge it has gained,
549	        // raised to the floor.
550	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
551	        return figure == null ? null : floored(claim, figure.add(lateCharge(claim, figure, sheet)), sheet);
552	    }
