554	    /** A claim's live figure as rates and grades are now, bound by no statement; null when its grade has
555	     *  no rate in force on its date. */
556	    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
557	        String sheetId = sheet.getId();
558	        return Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.gradeOn(claim.getDate())), claim.getDate())
559	                .map(Rate::getRate)
560	                .map(rate -> liveFigure(claim, rate, sheet.roundingFor(roundingDate(claim,
561	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))))
562	                .orElse(null);
563	    }
564	
565	    /** The due a claim shows as it is now: the due fixed when it was settled, else the one it would be settled at. */
566	    private BigDecimal shownDue(Sheet sheet, Claim claim, Person person) {
567	        return claim.getSettledDue() != null ? claim.getSettledDue() : dueNow(sheet, claim, person);
568	    }
569	
570	    private static String dueText(Claim claim) {
571	        return claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
572	    }
573	
574	    /** The next number for a claim dated on this day, opened now: within its period (<period name>-<n>, or X-<n>
575	     *  in no period) while the sheet's period numbering is on by its today, else the sheet's next number. */
576	    private String nextNumber(Sheet sheet, LocalDate date) {
577	        if (!sheet.numbersPerPeriod()) {
578	            return String.valueOf(sheet.nextClaimNumber());
579	        }
580	        String prefix = prefixOn(sheet, date);
581	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
582	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
583	        String number = sequence.next();
584	        sequences.save(sequence);
585	        return number;
586	    }
587	
588	    /** The prefix of the numbers given within the period a day is in: its name, or X in no period. */
589	    private String prefixOn(Sheet sheet, LocalDate date) {
590	        return periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
591	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
592	    }
593	
594	    /** Refuse to settle or approve a claim with no proofs whose due is above the proof threshold in force on its
595	     *  date (a claim with no due, or on a sheet with no threshold then, needs none). */
596	    private static void refuseUnproven(Sheet sheet, Claim claim, BigDecimal due) {
597	        BigDecimal threshold = sheet.proofThresholdOn(claim.getDate());
598	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
599	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
600	                    "A claim whose due is above the proof threshold of " + threshold + " needs a proof first");
601	        }
602	    }
603	
604	    /** Whether a settle by this user must wait for a steward: they are a clerk and the due is above the sheet's
605	     *  clerk limit (a claim with no due is within any limit). */
606	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
607	        BigDecimal limit = sheet.getClerkLimit();
608	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
609	            return false;
610	        }
611	        return !Role.STEWARD.equals(roles.roleOf(sheet.getId(), user));
612	    }
613	
614	    /** Refuse to void a SETTLED claim for anyone but a steward, and on a sheet's today more than
615	     *  {@value #SETTLED_VOID_DAYS} days after (or before) the day its log records it settled. */
616	    private void refuseSettledVoid(Sheet sheet, String user, Claim claim) {
617	        if (!Role.STEWARD.equals(roles.roleOf(sheet.getId(), user))) {
618	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
619	        }
620	        LocalDate settled = claim.settledOn();
621	        LocalDate today = sheet.getToday();
622	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(SETTLED_VOID_DAYS))) {
623	            throw new ResponseStatusException(HttpStatus.CONFLICT,
624	                    "A SETTLED claim can be voided only within " + SETTLED_VOID_DAYS + " days of its settlement");
625	        }
626	    }
627	
628	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
629	     *  and a claim that is not a correction but names one. */
630	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
631	        if (amount.signum() >= 0) {
632	            if (corrects != null) {
633	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
634	                        "Only a correction (a negative amount) names a claim it corrects");
635	            }
636	            return;
637	        }
638	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId).stream()
639	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
640	        if (!settled) {
641	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
642	                    "A correction must name the number of a SETTLED claim of the same person");
643	        }
644	    }
645	
646	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
647	    private void refuseIfClosed(String sheetId, LocalDate date) {
648	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
649	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
650	        }
651	    }
652	
653	    /** Refuse a claim dated after its person's retirement date. */
654	    private static void refuseIfRetired(Person person, LocalDate date) {
655	        if (person.refusesClaimOn(date)) {
656	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
657	                    "That claim is dated after " + person.getName() + " retired");
658	        }
659	    }
660	
661	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
662	    private static String entry(String event, String user, Person person, Claim claim, String number) {
663	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
664	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
665	                + (number == null ? "" : " number=" + number);
666	    }
667	
668	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
669	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
670	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
671	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
672	    }
673	
674	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
675	     *  claim of the same person it corrects. */
676	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
677	        if (claim.getCorrects() == null) {
678	            return claim.getDate();
679	        }
680	        return sheetClaims.stream()
681	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
682	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
683	    }
684	
685	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: for each
686	     *  full 30 days past the day it is due by, the late percent in force on that boundary date (its due-by plus 30, 60,
687	     *  90 ... days) of the figure, rounded as the claim rounds, added up; 0.00 when not overdue, it has no figure, or
688	     *  it is a correction. */
689	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
690	        BigDecimal none = BigDecimal.ZERO.setScale(2);
691	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
692	            return none;
693	        }
694	        return lateChargeAsOpen(claim, figure, sheet);
695	    }
696	
697	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
698	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet) {
699	        BigDecimal none = BigDecimal.ZERO.setScale(2);
700	        if (figure == null || claim.isCorrection()) {
701	            return none;
702	        }
703	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / 30;
704	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
705	        BigDecimal charge = none;
706	        for (long k = 1; k <= periods; k++) {
707	            charge = charge.add(dueOn(figure, sheet.latePctOn(claim.getDueBy().plusDays(30 * k)), rounding));
708	        }
709	        return charge;
710	    }
711	
712	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds. The floor is not applied
713	     *  to it: it is applied last, to the figure with its late charge (see {@link #floored(Claim, BigDecimal, Sheet)}). */
714	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, RoundingMode rounding) {
715	        return dueOn(claim.getAmount(), rate, rounding);
716	    }
717	
718	    /** A claim's due (its figure with its late charge) raised to the floor in force on its date, unless it is a
719	     *  correction. */
720	    public static BigDecimal floored(Claim claim, BigDecimal due, Sheet sheet) {
721	        return due == null || claim.isCorrection() || sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
722	    }
723	
724	    /** A live due raised to the sheet's floor when it is below it. */
725	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
726	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
727	    }
728	
729	    /** The terms in days a claim of the person dated {@code date} is due by: the person's own, else their grade's
730	     *  in force then, else the sheet's then. */
731	    private static int termsOf(Sheet sheet, Person person, LocalDate date) {
732	        return person.getTerms() != null ? person.getTerms() : sheet.termsFor(person.gradeOn(date), date);
733	    }
734	
735	    private static BigDecimal scaled(BigDecimal amount) {
736	        return amount.setScale(2, RoundingMode.UNNECESSARY);
737	    }
738	
739	    private static String noteOf(String note) {
740	        return note == null ? "" : note.trim();
741	    }
742	}
