    /** Archive the sheet, starting it if it has never been loaded. Who may archive it is checked by the caller;
     *  an archived sheet is refused before it gets here (see {@link ArchiveGuard}), and again under the lock. */
    @Transactional
    public Sheet archive(String id, String user) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        if (sheet.isArchived()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived");
        }
        sheet.archive();
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return saved;
    }

    /** Set the sheet's today, starting the sheet if it has never been loaded; then close every open period past its
     *  grace days. A change of today releases every claim editor's lock on the sheet. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        Rollup.Figures before = rollup.of(id);
        boolean changed = !today.equals(sheet.getToday());
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        periods.closePastGrace(saved, user);
        rollup.recordChanges(id, user, before);
        if (changed) {
            // Last, so no claim read before writes its lock back.
            claims.releaseLocks(id);
        }
        return saved;
    }

package net.officefloor.hq.app.role;

import java.util.Optional;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

/** Which steward, if any, a user acts for on a sheet's today. Kept apart from {@link DelegationService} so the audit
 *  sink and the role rules can ask it without depending on what records audit lines. */
@Component
public class Delegations {

    private final DelegationRepository delegations;
    private final SheetRepository sheets;

    public Delegations(DelegationRepository delegations, SheetRepository sheets) {
        this.delegations = delegations;
        this.sheets = sheets;
    }

    /** The steward who delegated the steward role to the user for a range holding the sheet's today (the latest such
     *  delegation), or empty when the user acts for no one. */
    @Transactional(readOnly = true)
    public Optional<String> actingFor(String sheetId, String user) {
        return sheets.findById(sheetId).map(Sheet::getToday).flatMap(today ->
                delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, user).stream()
                        .filter(d -> d.covers(today))
                        .map(Delegation::getDelegatedBy)
                        .findFirst());
    }
}

